ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS magazine_color TEXT NOT NULL DEFAULT '#FFA015';
ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS target_governorates JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS target_districts JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS target_areas JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS target_customer_types JSONB NOT NULL DEFAULT '[]'::jsonb;
CREATE TABLE IF NOT EXISTS public.offer_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, offer_id UUID NOT NULL REFERENCES public.offers(id) ON DELETE CASCADE, product_id BIGINT REFERENCES public.products(id) ON DELETE SET NULL, product_name TEXT NOT NULL, original_price NUMERIC(12,2) NOT NULL DEFAULT 0, offer_price NUMERIC(12,2) NOT NULL, discount_percentage NUMERIC(5,2), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.trader_market_post_interactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), post_id UUID NOT NULL REFERENCES public.trader_market_posts(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, interaction_type TEXT NOT NULL CHECK (interaction_type IN ('view','accept','reject')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(post_id,user_id,interaction_type));
CREATE TABLE IF NOT EXISTS public.story_views (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), story_id UUID NOT NULL REFERENCES public.stories(id) ON DELETE CASCADE, viewer_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, viewed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(story_id,viewer_id));